DO $$
DECLARE
  lo bigint := 0;
  step constant bigint := 20000;
BEGIN
  PERFORM set_config('statement_timeout', '0', false);
  PERFORM set_config('lock_timeout', '2s', false);
  WHILE lo <= (SELECT coalesce(max(id), 0) FROM orders) LOOP
    UPDATE orders SET email = '' WHERE id >= lo AND id < lo + step AND email IS NULL;
    COMMIT;
    lo := lo + step;
    PERFORM pg_sleep(0.02);
  END LOOP;
END $$;

DO $$
DECLARE i int;
BEGIN
  PERFORM set_config('lock_timeout', '200ms', true);
  IF EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'orders'::regclass AND conname = 'orders_email_not_null') THEN RETURN; END IF;
  FOR i IN 1..60 LOOP
    BEGIN
      ALTER TABLE orders ADD CONSTRAINT orders_email_not_null CHECK (email IS NOT NULL) NOT VALID;
      RETURN;
    EXCEPTION WHEN lock_not_available THEN
      PERFORM pg_sleep(0.5);
    END;
  END LOOP;
  RAISE EXCEPTION 'could not lock orders to add the check constraint';
END $$;

DO $$
DECLARE i int;
BEGIN
  PERFORM set_config('lock_timeout', '200ms', true);
  FOR i IN 1..60 LOOP
    BEGIN
      ALTER TABLE orders ALTER COLUMN email SET NOT NULL;
      ALTER TABLE orders DROP CONSTRAINT orders_email_not_null;
      RETURN;
    EXCEPTION WHEN lock_not_available THEN
      PERFORM pg_sleep(0.5);
    END;
  END LOOP;
  RAISE EXCEPTION 'could not lock orders to set NOT NULL';
END $$;
